// Command
public record PlaceOrderCommand(int CustomerId, List<OrderItem> Items)
    : IRequest<Guid>;

public class PlaceOrderHandler : IRequestHandler<PlaceOrderCommand, Guid>
{
    public async Task<Guid> Handle(PlaceOrderCommand request, CancellationToken ct)
    {
        // Validate, apply business rules, save
        var order = new Order { CustomerId = request.CustomerId };
        await _orderRepository.AddAsync(order);
        await _unitOfWork.CommitAsync();
        return order.Id;
    }
}

// Query
public record GetOrderDetailsQuery(Guid OrderId) : IRequest<OrderDetailsDto>;

public class GetOrderDetailsHandler : IRequestHandler<GetOrderDetailsQuery, OrderDetailsDto>
{
    public async Task<OrderDetailsDto> Handle(GetOrderDetailsQuery request, CancellationToken ct)
    {
        return await _readDbContext.OrdersDetails
            .Where(o => o.Id == request.OrderId)
            .Select(o => new OrderDetailsDto { ... })
            .FirstAsync(ct);
    }
}
